def longest_common_prefix(strings):
    if not strings:
        return ""

    min_length = min(len(s) for s in strings)
    prefix = ""

    for i in range(min_length):
        char_set = set(string[i] for string in strings)
        if len(char_set) == 1:
            prefix += strings[0][i]
        else:
            break

    return prefix

