def spiral_order(matrix):
    result = []
    while matrix:
        # Add the first row to the result and remove it from the matrix
        result += matrix.pop(0)
        # Add the last element of each remaining row (if any) and remove them
        if matrix and matrix[0]:
            for row in matrix:
                result.append(row.pop())
        # Add the last row in reverse order (if any) and remove it
        if matrix:
            result += matrix.pop()[::-1]
        # Add the first element of each remaining row in reverse order (if any) and remove them
        if matrix and matrix[0]:
            for row in matrix[::-1]:
                result.append(row.pop(0))
    return result

