def can_segment_string(s, dictionary):
    word_dict = set(dictionary)
    dp = [False] * (len(s) + 1)
    dp[0] = True

    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_dict:
                dp[i] = True
                break
    return dp[len(s)]

word = input().strip()
dictionary = input().strip().split()
print(can_segment_string(word, dictionary))

