def min_jumps(arr):
    n = len(arr)
    if n <= 1:
        return 0
    jumps = 0
    current_end = 0
    farthest = 0
    for i in range(n - 1):
        farthest = max(farthest, i + arr[i])
        if i == current_end:
            jumps += 1
            current_end = farthest
            if current_end >= n - 1:
                break
    return jumps

if __name__ == "__main__":
    arr = list(map(int, input().split()))
    print(min_jumps(arr))
